pm.test("Successful POST request", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});
const id = pm.response.json().id;

let ids = JSON.parse(pm.collectionVariables.get("patientIds") || "[]");
ids.push(id);

pm.collectionVariables.set("patientIds", JSON.stringify(ids));
pm.collectionVariables.set("patientId", id);

const deleted = pm.collectionVariables.get("patientId");

let ids = JSON.parse(pm.collectionVariables.get("patientIds") || "[]");
ids = ids.filter(x => x !== deleted);

pm.collectionVariables.set("patientIds", JSON.stringify(ids));
pm.collectionVariables.set("patientId", ids.length > 0 ? ids[ids.length - 1] : "");
